class Solution {
public:
    vector<string> braceExpansionII(string expression) {
        vector<vector<vector<string>>> groups;
        groups.push_back({});
        int level = 0;
        int start = 0;
        for (int i = 0; i < (int)expression.size(); ++i) {
            char c = expression[i];
            if (c == '{') {
                if (level == 0) start = i + 1;
                level++;
            } else if (c == '}') {
                level--;
                if (level == 0) {
                    vector<string> sub = braceExpansionII(expression.substr(start, i - start));
                    groups.back().push_back(sub);
                }
            } else if (level == 0) {
                if (c == ',') {
                    groups.push_back({});
                } else {
                    groups.back().push_back({string(1, c)});
                }
            }
        }
        set<string> unique_words;
        for (const auto& group : groups) {
            vector<string> combos = {""};
            for (const auto& word_set : group) {
                vector<string> next_combos;
                for (const string& prefix : combos) {
                    for (const string& w : word_set) {
                        next_combos.push_back(prefix + w);
                    }
                }
                combos = move(next_combos);
            }
            for (const string& s : combos) {
                unique_words.insert(s);
            }
        }
        return vector<string>(unique_words.begin(), unique_words.end());
    }
};

import java.util.*;

class Solution {
    public List<String> braceExpansionII(String expression) {
        List<List<List<String>>> groups = new ArrayList<>();
        groups.add(new ArrayList<>());
        int level = 0;
        int start = 0;
        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);
            if (c == '{') {
                if (level == 0) start = i + 1;
                level++;
            } else if (c == '}') {
                level--;
                if (level == 0) {
                    List<String> sub = braceExpansionII(expression.substring(start, i));
                    groups.get(groups.size() - 1).add(sub);
                }
            } else if (level == 0) {
                if (c == ',') {
                    groups.add(new ArrayList<>());
                } else {
                    groups.get(groups.size() - 1).add(Collections.singletonList(String.valueOf(c)));
                }
            }
        }
        Set<String> unique = new TreeSet<>();
        for (List<List<String>> group : groups) {
            List<String> combos = Collections.singletonList("");
            for (List<String> wordSet : group) {
                List<String> nextCombos = new ArrayList<>();
                for (String prefix : combos) {
                    for (String w : wordSet) {
                        nextCombos.add(prefix + w);
                    }
                }
                combos = nextCombos;
            }
            unique.addAll(combos);
        }
        return new ArrayList<>(unique);
    }
}

var braceExpansionII = function(expression) {
    const groups = [[]];
    let level = 0;
    let start = 0;
    for (let i = 0; i < expression.length; i++) {
        const c = expression[i];
        if (c === '{') {
            if (level === 0) start = i + 1;
            level++;
        } else if (c === '}') {
            level--;
            if (level === 0) {
                const sub = braceExpansionII(expression.substring(start, i));
                groups[groups.length - 1].push(sub);
            }
        } else if (level === 0) {
            if (c === ',') {
                groups.push([]);
            } else {
                groups[groups.length - 1].push([c]);
            }
        }
    }
    const res = new Set();
    for (const group of groups) {
        let combos = [''];
        for (const wordSet of group) {
            const nextCombos = [];
            for (const prefix of combos) {
                for (const w of wordSet) {
                    nextCombos.push(prefix + w);
                }
            }
            combos = nextCombos;
        }
        for (const word of combos) {
            res.add(word);
        }
    }
    return Array.from(res).sort();
};
